const shortPlanPreview=planPreview;
planPreview=function(){let root=document.createElement('div');root.innerHTML=shortPlanPreview();let target=root.querySelector('.f-document-page');if(target){let p=D.plans.find(x=>x.id===S.planId)||D.plans[0],paragraph='本人才培养方案以习近平新时代中国特色社会主义思想为指导，落实立德树人根本任务。围绕内蒙古区域产业发展、城市生命线智慧运行与企业岗位需求，构建知识、能力和素养相结合的专业课程体系。',rows=D.courses.map(c=>row([c.name,c.credits,c.term,c.abilities.slice(0,2).join('、')]));target.innerHTML=portalChapters.map((x,i)=>`<section class="f-long-chapter" id="preview-section-${i}"><h3>${x}</h3>${i===0?`<div class="f-missing-image">图片暂不可用，请联系管理员恢复原始附件。</div><h1>${safe(p.name)}</h1><p>内蒙古建筑职业技术大学 · ${p.year}</p>`:`<p>${paragraph}</p><p>${i<3?paragraph:'专业群对接电气设备运维、暖通运行、建筑智能化、给排水设备管理等岗位。课程设置依据典型工作任务和能力要求建立，形成课堂教学、实训教学与企业实践相衔接的培养路径。'}</p>${[5,6,8,9,10,11].includes(i)?table(['课程名称','学分','开课学期','支撑能力'],rows.slice((i*2)%Math.max(1,rows.length-4),(i*2)%Math.max(1,rows.length-4)+5)):`<p>${paragraph}</p>`}${i===10?`<div class="f-long-stat">组群专业 5 个　·　关联岗位 209 个　·　课程节点 2099 个</div>`:''}`}</section>`).join('')}return root.innerHTML};
