const researchSinglePage=researchPage;
researchPage=function(){let root=document.createElement('div');root.innerHTML=researchSinglePage();let paper=root.querySelector('.f-research-paper');if(paper){let sections=['摘要与核心结论','第一章 调研概况与数据说明','第二章 区域产业与就业面向','第三章 岗位需求与能力要求分析','第四章 行业技术变化与岗位发展','第五章 人才培养建议','附录 数据来源'],intro='围绕内蒙古自治区城市生命线智慧运行产业发展，结合企业岗位需求和课程能力支撑情况，形成专业调研分析。';paper.innerHTML=`<h2>供热通风与空调工程技术专业调研报告</h2><p>区域产业与专业建设依据 · 2026 年</p>${sections.map((title,i)=>`<section class="f-research-chapter" id="research-section-${i}"><h3>${title}</h3><p>${intro}</p><p>调研样本涵盖关联企业、招聘岗位、典型任务、能力要求和培养方案。分析结果用于演示产品逻辑，具体人数与图表为预设数据。</p>${i>0&&i<6?table(['维度','样本量','主要发现','建议'],[['企业需求',92,'设备维护与系统调试持续增长','补充实训任务'],['岗位样本',209,'安全操作和数据分析成为共性要求','优化课程能力映射'],['课程支撑',D.courses.length,'核心能力已有课程覆盖','强化综合项目']].map(row)):''}${i===3?`<div class="ref-horizontal-bars">${D.positions.slice(0,5).map((p,j)=>`<button data-action="job-open" data-value="${p.id}"><span>${p.name}</span><i style="width:${85-j*12}%"></i><em>${60-j*8}</em></button>`).join('')}</div>`:''}</section>`).join('')}`;root.insertAdjacentHTML('beforeend',`<div class="f-research-evidence"><section class="ref-panel"><h3>报告信息</h3><p>供热通风与空调工程技术专业调研报告</p><small>生成时间：2026-11-25　·　状态：已保存</small></section><section class="ref-panel"><h3>导出与留存</h3><button class="btn" data-action="research-export">导出文本</button><button class="btn" data-action="research-export-html">导出 HTML</button></section></div>`)}return root.innerHTML};
