standardEdit=function(){let root=document.createElement('div');root.innerHTML=shortStandardEditor();let body=root.querySelector('.f-standard-editor>section'),c=D.courses.find(x=>x.id===S.selectedCourse)||D.courses[0];if(body){let blocks=[['课程教学目标','项目模块','素质目标','知识目标','能力目标'],['课程内容与学时分配','项目模块','任务单元','教学内容','学时'],['课程考核与评价','考核项目','考核方式','成绩占比','评价依据'],['教学资源','资源类型','资源名称','使用场景','来源'],['教学实施保障','保障项目','条件要求','责任部门','说明'],['课程建设团队','姓名','工作单位','职称职务','职责'],['参考材料','资料名称','类型','来源','更新时间']];for(const [title,...headers] of blocks){body.insertAdjacentHTML('beforeend',`<section class="f-standard-block"><header><b>${title}</b>${tag('表格')}<span>共 4 行</span><button class="btn primary" data-action="ai-standard">✧ AI ⌄</button></header><div class="f-standard-table"><p>课程标准要素 · 固定演示内容 <button class="btn" data-action="standard-add-row">＋ 行</button></p>${table(headers,Array.from({length:4},(_,i)=>row([`<input value="${i+1}. ${D.positions[i%D.positions.length].task}">`,`<input value="${D.courses[i%D.courses.length].name}">`,`<input value="${D.positions[i%D.positions.length].skills[0]}">`,`<input value="${i%2?'32 学时':'24 学时'}">`])))}</div></section>`)}body.insertAdjacentHTML('beforeend',`<section class="f-standard-block"><header><b>其他说明</b>${tag('文本')}<span>模拟数据</span><button class="btn primary" data-action="ai-standard">✧ AI ⌄</button></header><textarea class="f-standard-text">本课程标准依据专业群人才培养方案与岗位能力图谱编制，实施过程应结合企业真实项目和区域行业标准。</textarea></section><section class="f-standard-block"><header><b>参考附件</b>${tag('附件')}</header><div class="f-standard-table"><label class="btn">⇧ 上传参考资料（模拟解析）<input type="file" id="file-upload" hidden></label><p>上传后仅显示固定解析结果，不连接后端服务。</p></div></section>`);let saved=c.standardBlocks||[];body.querySelectorAll('textarea').forEach((x,i)=>{if(saved[i]!==undefined)x.textContent=saved[i]})}return root.innerHTML};
const basicTemplateEditor=templateEditPage;
templateEditPage=function(){let root=document.createElement('div');root.innerHTML=basicTemplateEditor();let tab=S.templateTab||'基础信息',panel=root.querySelector('.ref-panel');if(!panel||tab==='基础信息')return root.innerHTML;let t=D.templates.find(x=>x.id===S.editingTemplate)||D.templates[0];let content=tab==='关联参数'?`${table(['参数名称','参数代码','类型','默认值','操作'],[['产业链名称','industryName','文本','城市生命线智慧运行'],['专业群','majorName','文本',I.group],['区域','province','文本','内蒙古自治区'],['年度','year','数字','2026'],['岗位需求','jobCount','数字','209']].map(x=>row([`<input value="${x[0]}">`,`<input value="${x[1]}">`,x[2],`<input value="${x[3]}">`,`<button class="link" data-action="template-row-delete">删除</button>`])))}<button class="btn" data-action="template-row-add">＋ 添加参数</button>`:tab==='报告目录'?`<div class="f-template-outline">${['执行摘要','专业群概况','上游产业链分析','中游产业链分析','下游产业链分析','产业链整体分析','结论与专业建设建议'].map((x,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><input value="${x}"><button class="link" data-action="template-row-delete">删除</button></div>`).join('')}</div><button class="btn" data-action="template-row-add">＋ 新增章节</button>`:tab==='内部数据'?`<p class="f-panel-desc">配置可用于报告生成的内部数据资产。所有数据均为本地演示样本。</p>${['产业链全景','企业与招聘岗位','岗位能力图谱','课程岗位关联','培养方案','企业需求'].map((x,i)=>`<label class="f-template-asset"><input type="checkbox" ${i<4?'checked':''}><b>${x}</b><small>${[2278,3515,1348,2099,2,2][i]} 条演示记录</small></label>`).join('')}`:`<div class="f-template-generating"><div class="notice">生成规则使用固定结果，仅供演示。</div><div class="field"><label>系统提示词</label><textarea>你是产业链调研报告助手。根据专业群、企业、岗位和课程数据，按报告目录输出结构化分析。</textarea></div><div class="field"><label>生成要求</label><textarea>报告应包含产业链概况、岗位需求、能力要求、课程支撑和建设建议。所有结论标注数据来源。</textarea></div><label><input type="checkbox" checked> 生成后自动保存为草稿</label></div>`;panel.innerHTML=`<div class="ref-panel-head"><h2>${tab}</h2><button class="btn" data-action="template-row-add">＋ 新增${tab==='报告目录'?'章节':'配置'}</button></div>${content}<div class="f-action-row"><button class="btn" data-route="templates">取消</button><button class="btn primary" data-action="template-config-save">保存配置</button></div>`;let stored=t.config?.[tab];if(Array.isArray(stored))root.querySelectorAll('.ref-panel input:not([type=checkbox]),.ref-panel textarea').forEach((x,i)=>{if(stored[i]!==undefined){if(x.tagName==='TEXTAREA')x.textContent=stored[i];else x.setAttribute('value',stored[i])}});return root.innerHTML};
