  if(S.modal==='report-settings'){const r=D.reports.find(x=>x.id===S.editingReport)||D.reports[0],settings=r.settings||{};return `<div class="modal-backdrop" data-action="backdrop"><div class="modal f-report-dialog settings"><div class="modal-head">报告设置<button data-action="close-modal">×</button></div><div class="modal-body"><div class="notice">修改报告范围后，系统会重新查询模板内部数据；现有正文不会自动覆盖。</div>${[['报告模板','产业链洞察报告模板','readonly'],['报告名称',settings.name||r.name],['学校名称',settings.school||I.schools],['专业群名称',settings.major||I.group],['报告年度',settings.year||'2026'],['区域',settings.region||'内蒙古自治区'],['产业链',settings.chain||I.industry]].map((x,i)=>`<div class="f-report-setting-row"><label>${i>0&&i!==5?'＊':''}${x[0]}</label><input id="report-setting-${i}" value="${safe(x[1])}" ${x[2]||''}></div>`).join('')}</div><div class="modal-foot"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="report-settings-save">保存设置</button></div></div></div>`}
