reportEdit=function(){let root=document.createElement('div');root.innerHTML=referenceReportEditor();const head=root.querySelector('.f-report-editor-head');head?.insertAdjacentHTML('beforeend','<button class="btn" data-action="report-data-toggle">▤ 数据源</button>');root.insertAdjacentHTML('beforeend',`<section class="f-report-data-panel"><div class="f-report-data-settings">${['生成表','生成表格','加附表','加引用','加水印'].map(x=>`<label><span>${x}</span><input type="checkbox"></label>`).join('')}</div><div class="f-report-data-main"><div class="f-report-data-head"><b>数据源　12/12</b><small>勾选的指标和数据集将作为全文统一的 AI 数据依据</small></div><div class="f-report-data-tabs"><button class="${(S.reportDataTab||'内部数据')==='内部数据'?'active':''}" data-action="report-data-tab" data-value="内部数据">内部数据　12</button><button class="${S.reportDataTab==='外部数据'?'active':''}" data-action="report-data-tab" data-value="外部数据">外部数据　0</button></div>${S.reportDataTab==='外部数据'?`<div class="f-report-upload"><b>暂无外部数据源</b><p>可从 Excel 导入任意结构的指标或数据集</p><label class="btn">⇧ 导入 Excel（模拟解析）<input type="file" class="f-report-data-upload" hidden></label></div>`:`<div class="f-report-data-items">${['产业链企业数','岗位招聘记录','岗位能力要求','课程支撑关系'].map(x=>`<label><input type="checkbox" checked> ${x}</label>`).join('')}</div>`}</div><div class="f-report-reference"><b>参考资料　0/0</b><small>上传文档资料，作为全文生成与 AI 编辑的事实参考</small><div class="f-report-upload"><b>尚未添加参考资料</b><p>支持 PDF、Word、PPT、TXT 等文档</p><label class="btn">⇧ 上传资料（模拟解析）<input type="file" class="f-report-data-upload" hidden></label></div></div></section>`);return root.innerHTML};
standardEdit=function(){
  const root=document.createElement('div');root.innerHTML=longStandardEditor();
  const c=D.courses.find(x=>x.id===S.selectedCourse)||D.courses[0];
  root.querySelectorAll('.f-standard-block tbody').forEach((tbody,i)=>{
    const target=Math.min(c.standardRowCounts?.[i]||tbody.children.length,30);
    while(tbody.children.length<target)tbody.appendChild(tbody.lastElementChild.cloneNode(true));
  });
  root.querySelectorAll('.f-standard-block input:not([type=file])').forEach((input,i)=>{if(c.standardInputs?.[i]!==undefined)input.setAttribute('value',c.standardInputs[i])});
  return root.innerHTML;
};
