  if(a==='news-preview-page'){S.newsPreviewPage=Number(v);render();return}
  if(a==='news-preview-zoom'){S.newsPreviewZoom=Number(v);render();return}
  if(a==='news-preview-download'){download('前沿动态资料预览.html',`<!doctype html><meta charset="utf-8"><h1>${safe(S.modalValue||'前沿动态资料')}</h1><p>内蒙古专业群能力图谱平台 · 模拟预览资料</p>`,'text/html;charset=utf-8');return}
  if(a==='standard-import'){S.standardImportTab='已传附件解析';S.modal='standard-import';render();return}
