  if(a==='standard-import-confirm'){const textValue=el('standard-import-text')?.value.trim();if(!textValue){toast('暂无可导入内容，请粘贴课标文本或上传附件');return}const c=D.courses.find(x=>x.id===S.selectedCourse)||D.courses[0];c.standardText=(c.standardText||'')+'\n\n（模拟解析导入）'+textValue;persist();S.modal=null;render();toast('课程标准已模拟解析并导入');return}
