  if(a==='create-report'&&S.modal==='new-report'){const name=el('new-report-name')?.value.trim(),chain=el('new-report-chain')?.value.trim();if(!name||!chain){toast('请填写报告名称和产业链');return}const r={id:'r'+Date.now(),name,scope:`${el('new-report-region')?.value||'内蒙古自治区'} · ${el('new-report-year')?.value||'2026'}年`,status:'草稿',updated:'2026-11-25',templateId:S.newReportTemplate,settings:{name,school:el('new-report-school')?.value,major:el('new-report-major')?.value,year:el('new-report-year')?.value,region:el('new-report-region')?.value,chain}};D.reports.unshift(r);persist();S.editingReport=r.id;S.reportContent='';S.modal=null;go('report-edit');toast('报告草稿已创建');return}
